<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Billiards</title>
    <style>
        * { margin: 0; padding: 0; box-sizing: border-box; }
        body {
            display: flex;
            flex-direction: column;
            align-items: center;
            justify-content: center;
            min-height: 100vh;
            background: #2a5a3a;
            font-family: Arial, sans-serif;
        }
        h1 { color: #fff; margin-bottom: 10px; }
        #canvas {
            display: block;
            border: 5px solid #8b4513;
            background: #0d3a0d;
            margin: 20px auto;
            cursor: crosshair;
        }
        .controls {
            margin: 20px 0;
        }
        button {
            padding: 10px 20px;
            font-size: 16px;
            background: #4a90e2;
            color: white;
            border: none;
            border-radius: 5px;
            cursor: pointer;
        }
        button:hover { background: #357abd; }
        .instructions {
            color: #fff;
            background: rgba(0,0,0,0.6);
            padding: 15px;
            border-radius: 5px;
            max-width: 600px;
            margin: 20px auto;
            font-size: 13px;
            line-height: 1.6;
        }
    </style>
</head>
<body>
    <h1>Billiards</h1>
    <canvas id="canvas" width="1200" height="600"></canvas>
    <div class="instructions">
        <strong>How to Play:</strong><br>
        Click and drag the white ball backward to aim. Release to shoot. Longer drag = more power.
        Red balls sink in pockets. Click <strong>Reset</strong> to rack the table.
    </div>
    <div class="controls">
        <button id="resetBtn">Reset</button>
    </div>

    <script>
        const canvas = document.getElementById('canvas');
        const ctx = canvas.getContext('2d');

        const W = 1200, H = 600, R = 7.5;
        const FRICTION = 0.985, POCKET_RADIUS = 15;
        const POCKETS = [
            {x: R, y: R}, {x: W - R, y: R},
            {x: R, y: H - R}, {x: W - R, y: H - R},
            {x: W/2, y: R}, {x: W/2, y: H - R}
        ];

        class Ball {
            constructor(x, y, vx = 0, vy = 0, cue = false) {
                this.x = x; this.y = y;
                this.vx = vx; this.vy = vy;
                this.cue = cue; this.potted = false;
            }
            get speed() { return Math.hypot(this.vx, this.vy); }
        }

        const sim = {
            W, H, R, balls: [], running: true,

            reset(balls) {
                this.balls = balls.map(b => 
                    new Ball(b.x, b.y, b.vx || 0, b.vy || 0, b.cue || false)
                );
            },

            step(dt) {
                const steps = Math.round(dt * 60);
                for (let s = 0; s < steps; s++) {
                    for (let ball of this.balls) {
                        if (!ball.potted) {
                            ball.x += ball.vx;
                            ball.y += ball.vy;
                            ball.vx *= FRICTION;
                            ball.vy *= FRICTION;
                            if (ball.speed < 0.05) ball.vx = ball.vy = 0;
                        }
                    }

                    for (let ball of this.balls) {
                        if (ball.potted) continue;
                        if (ball.x - R < 0) {
                            ball.x = R;
                            ball.vx = Math.abs(ball.vx) * 0.95;
                        }
                        if (ball.x + R > W) {
                            ball.x = W - R;
                            ball.vx = -Math.abs(ball.vx) * 0.95;
                        }
                        if (ball.y - R < 0) {
                            ball.y = R;
                            ball.vy = Math.abs(ball.vy) * 0.95;
                        }
                        if (ball.y + R > H) {
                            ball.y = H - R;
                            ball.vy = -Math.abs(ball.vy) * 0.95;
                        }
                    }

                    for (let ball of this.balls) {
                        if (ball.potted) continue;
                        for (let pocket of POCKETS) {
                            if (Math.hypot(ball.x - pocket.x, ball.y - pocket.y) < POCKET_RADIUS) {
                                ball.potted = true;
                                ball.vx = ball.vy = 0;
                            }
                        }
                    }

                    for (let i = 0; i < this.balls.length; i++) {
                        for (let j = i + 1; j < this.balls.length; j++) {
                            const b1 = this.balls[i], b2 = this.balls[j];
                            if (b1.potted || b2.potted) continue;
                            const dx = b2.x - b1.x, dy = b2.y - b1.y;
                            const dist = Math.hypot(dx, dy);
                            if (dist < 2 * R && dist > 0) {
                                const nx = dx / dist, ny = dy / dist;
                                const dvDotN = (b2.vx - b1.vx) * nx + (b2.vy - b1.vy) * ny;
                                if (dvDotN < 0) {
                                    b1.vx += dvDotN * nx * 0.95;
                                    b1.vy += dvDotN * ny * 0.95;
                                    b2.vx -= dvDotN * nx * 0.95;
                                    b2.vy -= dvDotN * ny * 0.95;
                                    const overlap = 2 * R - dist;
                                    b1.x -= overlap * nx / 2;
                                    b1.y -= overlap * ny / 2;
                                    b2.x += overlap * nx / 2;
                                    b2.y += overlap * ny / 2;
                                }
                            }
                        }
                    }
                }
                this.render();
            },

            state() {
                return this.balls.map(b => ({
                    x: b.x, y: b.y, vx: b.vx, vy: b.vy,
                    potted: b.potted, cue: b.cue
                }));
            },

            shoot(vx, vy) {
                for (let ball of this.balls) {
                    if (ball.cue) { ball.vx = vx; ball.vy = vy; break; }
                }
            },

            pause() { this.running = false; },
            resume() { this.running = true; },

            render() {
                ctx.fillStyle = '#0a4d0a';
                ctx.fillRect(0, 0, W, H);
                ctx.strokeStyle = '#6b4423';
                ctx.lineWidth = 20;
                ctx.strokeRect(R, R, W - 2*R, H - 2*R);
                ctx.fillStyle = '#1a1a1a';
                for (let p of POCKETS) {
                    ctx.beginPath();
                    ctx.arc(p.x, p.y, POCKET_RADIUS, 0, 2 * Math.PI);
                    ctx.fill();
                }
                for (let ball of this.balls) {
                    if (!ball.potted) {
                        ctx.fillStyle = ball.cue ? '#ffffff' : '#e74c3c';
                        ctx.beginPath();
                        ctx.arc(ball.x, ball.y, R, 0, 2 * Math.PI);
                        ctx.fill();
                        ctx.strokeStyle = '#333';
                        ctx.lineWidth = 1;
                        ctx.stroke();
                    }
                }
            }
        };

        let isDragging = false, dragStartX = 0, dragStartY = 0;
        let mouseX = 0, mouseY = 0, cueBall = null;

        function getCueBall() {
            for (let b of sim.balls) if (b.cue && !b.potted) return b;
            return null;
        }

        canvas.addEventListener('mousedown', (e) => {
            cueBall = getCueBall();
            if (!cueBall || cueBall.speed > 0.5) return;
            const rect = canvas.getBoundingClientRect();
            const x = e.clientX - rect.left, y = e.clientY - rect.top;
            if (Math.hypot(x - cueBall.x, y - cueBall.y) < R * 3) {
                isDragging = true;
                dragStartX = x;
                dragStartY = y;
            }
        });

        canvas.addEventListener('mousemove', (e) => {
            const rect = canvas.getBoundingClientRect();
            mouseX = e.clientX - rect.left;
            mouseY = e.clientY - rect.top;
        });

        canvas.addEventListener('mouseup', (e) => {
            if (!isDragging || !cueBall) return;
            const dx = dragStartX - mouseX;
            const dy = dragStartY - mouseY;
            sim.shoot(dx * 0.25, dy * 0.25);
            isDragging = false;
        });

        document.getElementById('resetBtn').addEventListener('click', () => {
            const balls = [
                {x: W * 0.75, y: H / 2, cue: true},
                {x: W * 0.25, y: H / 2 - R * 2},
                {x: W * 0.25, y: H / 2},
                {x: W * 0.25, y: H / 2 + R * 2},
                {x: W * 0.25 - R * 1.5, y: H / 2 - R},
                {x: W * 0.25 - R * 1.5, y: H / 2 + R},
                {x: W * 0.25 - R * 3, y: H / 2}
            ];
            sim.reset(balls);
            isDragging = false;
            cueBall = getCueBall();
            sim.render();
        });

        document.getElementById('resetBtn').click();

        let lastTime = performance.now();
        function animate() {
            if (sim.running) {
                const now = performance.now();
                const dt = Math.min((now - lastTime) / 1000, 0.016);
                lastTime = now;
                sim.step(dt);
            }

            if (isDragging && cueBall) {
                ctx.strokeStyle = 'rgba(255, 200, 100, 0.7)';
                ctx.lineWidth = 2;
                ctx.beginPath();
                ctx.moveTo(cueBall.x, cueBall.y);
                ctx.lineTo(mouseX, mouseY);
                ctx.stroke();
                const power = Math.hypot(dragStartX - mouseX, dragStartY - mouseY) / 100;
                ctx.fillStyle = 'rgba(255, 200, 100, 0.3)';
                ctx.fillRect(cueBall.x - 40, cueBall.y + 20, 80, 8);
                ctx.fillStyle = 'rgba(255, 200, 100, 0.8)';
                ctx.fillRect(cueBall.x - 40, cueBall.y + 20, Math.min(80, power * 8), 8);
            }

            requestAnimationFrame(animate);
        }
        animate();

        window.sim = sim;
    </script>
</body>
</html>
